<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  :root{
    --bg:#12141a;
    --panel:#1b1e26;
    --cell:#252932;
    --text:#e8eaf0;
    --muted:#9aa2b1;
    --accent:#f2b179;
  }
  *{box-sizing:border-box;}
  html,body{height:100%;}
  body{
    margin:0;
    background:var(--bg);
    color:var(--text);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    min-height:100vh;
    padding:24px;
    user-select:none;
  }
  h1{
    margin:0 0 14px;
    font-size:34px;
    letter-spacing:2px;
    font-weight:800;
  }
  .bar{
    width:400px;
    max-width:90vw;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    margin-bottom:14px;
  }
  .scorebox{
    background:var(--panel);
    border-radius:10px;
    padding:8px 18px;
    text-align:center;
    min-width:120px;
  }
  .scorebox .label{
    font-size:11px;
    letter-spacing:2px;
    text-transform:uppercase;
    color:var(--muted);
  }
  #score{
    font-size:24px;
    font-weight:700;
    line-height:1.2;
  }
  #reset{
    background:var(--accent);
    color:#1b1e26;
    border:none;
    border-radius:10px;
    padding:12px 20px;
    font-size:15px;
    font-weight:700;
    cursor:pointer;
  }
  #reset:hover{filter:brightness(1.08);}
  #board{
    width:400px;
    max-width:90vw;
    aspect-ratio:1/1;
    background:var(--panel);
    border-radius:12px;
    padding:10px;
    display:grid;
    grid-template-columns:repeat(4,1fr);
    grid-template-rows:repeat(4,1fr);
    gap:10px;
  }
  .tile{
    background:var(--cell);
    border-radius:8px;
    display:flex;
    align-items:center;
    justify-content:center;
    font-size:30px;
    font-weight:700;
    color:var(--text);
  }
  .tile.v0{color:transparent;}
  .tile.v2{background:#3a3f4b;}
  .tile.v4{background:#464c5b;}
  .tile.v8{background:#b3714e;color:#fff;}
  .tile.v16{background:#c4703c;color:#fff;}
  .tile.v32{background:#d1603b;color:#fff;}
  .tile.v64{background:#dd4d30;color:#fff;}
  .tile.v128{background:#c9b458;color:#1b1e26;font-size:26px;}
  .tile.v256{background:#cdb54a;color:#1b1e26;font-size:26px;}
  .tile.v512{background:#d2b13c;color:#1b1e26;font-size:26px;}
  .tile.v1024{background:#d8ae2d;color:#1b1e26;font-size:20px;}
  .tile.v2048{background:#e0ab17;color:#1b1e26;font-size:20px;}
  .tile.big{background:#5c4bd8;color:#fff;font-size:18px;}
  .hint{margin-top:14px;color:var(--muted);font-size:13px;}
</style>
</head>
<body>
  <h1>2048</h1>
  <div class="bar">
    <div class="scorebox">
      <div class="label">Score</div>
      <div id="score">0</div>
    </div>
    <button id="reset" type="button">New Game</button>
  </div>
  <div id="board" aria-label="2048 board"></div>
  <div class="hint">Use the arrow keys to move the tiles.</div>

<script>
(function () {
  var SIZE = 4;
  var boardEl = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var resetEl = document.getElementById('reset');

  var grid = emptyGrid();
  var score = 0;
  var cells = [];

  function emptyGrid() {
    var g = [];
    for (var r = 0; r < SIZE; r++) {
      var row = [];
      for (var c = 0; c < SIZE; c++) row.push(0);
      g.push(row);
    }
    return g;
  }

  function buildCells() {
    boardEl.innerHTML = '';
    cells = [];
    for (var i = 0; i < SIZE * SIZE; i++) {
      var d = document.createElement('div');
      d.className = 'tile v0';
      boardEl.appendChild(d);
      cells.push(d);
    }
  }

  function render() {
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = grid[r][c];
        var el = cells[r * SIZE + c];
        el.textContent = v ? String(v) : '';
        var cls = 'tile ';
        if (v === 0) cls += 'v0';
        else if (v <= 2048) cls += 'v' + v;
        else cls += 'big';
        el.className = cls;
      }
    }
    scoreEl.textContent = String(score);
  }

  function cloneGrid(g) {
    return g.map(function (row) { return row.slice(); });
  }

  function transpose(g) {
    var out = emptyGrid();
    for (var r = 0; r < SIZE; r++)
      for (var c = 0; c < SIZE; c++) out[c][r] = g[r][c];
    return out;
  }

  function reverseRows(g) {
    return g.map(function (row) { return row.slice().reverse(); });
  }

  // Slide + merge one row toward the left. Each tile merges at most once.
  function slideRowLeft(row) {
    var vals = row.filter(function (v) { return v !== 0; });
    var out = [];
    var gained = 0;
    for (var i = 0; i < vals.length; i++) {
      if (i + 1 < vals.length && vals[i] === vals[i + 1]) {
        var merged = vals[i] * 2;
        out.push(merged);
        gained += merged;
        i++; // consume the partner so it cannot merge again
      } else {
        out.push(vals[i]);
      }
    }
    while (out.length < SIZE) out.push(0);
    return { row: out, gained: gained };
  }

  function toLeftSpace(g, dir) {
    if (dir === 'left') return cloneGrid(g);
    if (dir === 'right') return reverseRows(g);
    if (dir === 'up') return transpose(g);
    if (dir === 'down') return reverseRows(transpose(g));
    return null;
  }

  function fromLeftSpace(g, dir) {
    if (dir === 'left') return cloneGrid(g);
    if (dir === 'right') return reverseRows(g);
    if (dir === 'up') return transpose(g);
    if (dir === 'down') return transpose(reverseRows(g));
    return null;
  }

  function sameGrid(a, b) {
    for (var r = 0; r < SIZE; r++)
      for (var c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  function emptyCells() {
    var list = [];
    for (var r = 0; r < SIZE; r++)
      for (var c = 0; c < SIZE; c++)
        if (grid[r][c] === 0) list.push([r, c]);
    return list;
  }

  function spawn() {
    var list = emptyCells();
    if (!list.length) return false;
    var pick = list[Math.floor(Math.random() * list.length)];
    grid[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function move(dir) {
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') return false;
    var before = cloneGrid(grid);
    var work = toLeftSpace(grid, dir);
    var gained = 0;
    for (var r = 0; r < SIZE; r++) {
      var res = slideRowLeft(work[r]);
      work[r] = res.row;
      gained += res.gained;
    }
    var after = fromLeftSpace(work, dir);
    if (sameGrid(before, after)) return false;
    grid = after;
    score += gained;
    spawn();
    render();
    return true;
  }

  function reset() {
    grid = emptyGrid();
    score = 0;
    spawn();
    spawn();
    render();
  }

  function setBoard(arr) {
    var g = emptyGrid();
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = arr && arr[r] ? arr[r][c] : 0;
        g[r][c] = Number(v) || 0;
      }
    }
    grid = g;
    render();
  }

  var KEYS = {
    ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down',
    Left: 'left', Right: 'right', Up: 'up', Down: 'down'
  };

  document.addEventListener('keydown', function (e) {
    var dir = KEYS[e.key];
    if (!dir) return;
    e.preventDefault();
    move(dir);
  });

  resetEl.addEventListener('click', function () { reset(); });

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: function () { return cloneGrid(grid); },
    setBoard: setBoard,
    score: function () { return score; }
  };

  buildCells();
  reset();
})();
</script>
</body>
</html>
